import squishtest3
import sys
from squishtest3 import test
import time
import threading

def xLog(msg):
    '''
    A sample logging approach
    '''
    #test.log(msg)  # Note: commented out to remove dependency on squish test report
    print(msg)

def log_decorator(func):
    '''
    Logging decorator
    '''
    def wrapper(*args, **kwargs):
        if getattr(func, 'skip_logging', False):
            return func(*args, **kwargs)
        if callable(func):
            try:
                pre = f'<{func.__qualname__}'
                pre += (f' args="{args}"').replace('<', '&lt;').replace('>','&gt;') if args else ''
                pre += (f' kwargs="{kwargs}"').replace('<', '&lt;').replace('>','&gt;') if kwargs else ''
                pre += '>'
                xLog(pre)
                result = func(*args, **kwargs)
                post = '</' + f'{func.__qualname__}>' + (f' <!-- returned {result} --> ' if result is not None else '')
                xLog(post)
                return result
            except Exception:
                # Handle exceptions if any
                exc_type, exc_value, exc_traceback = sys.exc_info()
                errmsg = f' <!-- <Exception><Type>{exc_type}</Type><Value>{exc_value}</Value><Traceback>{exc_traceback}</Traceback></Exception> -->\n'
                errmsg += f'</{func.__qualname__}>'
                xLog(errmsg)
        elif isinstance(func, property):
            pre = ''
            post = ''
            try:
                if func.fset and len(args) > 1:
                    pre = f'<{func.fset.__qualname__}>'
                    args_str = ', '.join(map(str, args[1:])) if len(args) > 1 else ''
                    pre += ' set: ' + args_str
                    result = func.fset(*args, **kwargs)
                    post =  (f' (return: {result} )' if result is not None else ' ') + f'</{func.fset.__qualname__}>'
                    xLog(pre + post)
                    return result
                elif func.fget and len(args) == 1:
                    pre = f'<{func.fget.__qualname__}>'
                    result = func.fget(*args, **kwargs)
                    post =  (f' get: {result} ' if result is not None else ' ') + f'</{func.fget.__qualname__}>'
                    xLog(pre + post)
                    return result
                elif func.fdel:
                    pre = f'<{func.fdel.__qualname__}>'
                    pre += ' del '
                    result = func.fdel(*args, **kwargs)
                    post =  (f' {result} ' if result is not None else ' ') + f'</{func.fdel.__qualname__}>'
                    xLog(pre + post)
                    return result
            except Exception:
                xLog(pre + post)
                # Handle exceptions if any
                exc_type, exc_value, exc_traceback = sys.exc_info()
                errmsg = f' <!-- <Exception><Type>{exc_type}</Type><Value>{exc_value}</Value><Traceback>{exc_traceback}</Traceback></Exception> -->\n'
                errmsg += f'</{func.fset.__qualname__}>' if func.fset else f'</{func.fget.__qualname__}>' if func.fget else f'</{func.fdel.__qualname__}>' if func.fdel else ''
                xLog(errmsg)
    return wrapper

def skip_logging(func):
    '''
    Add this to skip logging for a method of a class inherited from LogMeta
    '''
    func.skip_logging = True
    return func

def skip_log_decorator(skip_condition):
    '''
    Use this to skip logging for a function.
    For a method of a class inherited from LogMeta, just add decorator @skip_logging
    '''
    def decorator(func):
        def wrapper(*args, **kwargs):
            if skip_condition:
                func.skip_logging = True
            return func(*args, **kwargs)
        return wrapper
    return decorator

def call_once(func):
    '''
    The decorator is used to make sure the marked function only being called once.
    '''
    called = False
    def wrapper(*args, **kwargs):
        nonlocal called
        if not called:
            called = True
            return func(*args, **kwargs)
    return wrapper

class LogMeta(type):
    '''
    A base class for classes that need logging for their methods
    '''
    def __new__(cls, name, bases, dct):
        for key, value in dct.items():
            if callable(value):
                dct[key] = log_decorator(value)
            elif isinstance(value, property):
                if value.fget:
                    dct[key] = property(log_decorator(value), log_decorator(value) if value.fset else None, log_decorator(value) if value.fdel else None)
        return super().__new__(cls, name, bases, dct)

def run_in_application_context(expected_aut):
    '''
    The decorator function is used to ensure the current context is from the expected aut
    '''
    def decorator(func):
        def wrapper(*args, **kwargs):
            current_aut = squishtest3.currentApplicationContext().name

            def context_monitor():
                while not stop_monitor:
                    if squishtest3.currentApplicationContext().name != expected_aut:
                        apps = squishtest3.applicationContextList()
                        try:
                            app_handle = next(handle for handle in apps if handle.name == expected_aut and len(apps) != 0)
                            squishtest3.setApplicationContext(app_handle)
                        except Exception:
                            pass
                    time.sleep(interval)

            if current_aut == expected_aut:
                # Start context monitoring thread
                stop_monitor = False
                interval = .5  # Adjust the interval as needed
                monitor_thread = threading.Thread(target=context_monitor)
                monitor_thread.start()

                # Execute the function
                result = func(*args, **kwargs)

                # Stop context monitoring thread
                stop_monitor = True
                monitor_thread.join()
            else:
                xLog(f"Error: Function '{func.__name__}' can only run in the '{expected_aut}' context.")
                result = None
            return result
        return wrapper
    return decorator
